import{c as e}from"./app.756eaed4.js";import{_ as i}from"./plugin-vue_export-helper.21dcd24c.js";const t={},d=e('<h1 id="editing-segment-fields" tabindex="-1"><a class="header-anchor" href="#editing-segment-fields" aria-hidden="true">#</a> Editing segment fields</h1><p>You can add, edit, move, and delete fields for a segment from the field table view.</p><h2 id="adding-and-editing-fields" tabindex="-1"><a class="header-anchor" href="#adding-and-editing-fields" aria-hidden="true">#</a> Adding and editing fields</h2><p><strong>To add a field:</strong></p><ol><li>In the field table view, click <strong>Add</strong>.</li><li>In the <strong>Add field</strong> menu, specify the field options, including the field type (IMS field or user-defined field) and any applicable data converter.</li><li>Click <strong>OK</strong> to save the field.</li></ol><p><strong>To edit a field:</strong></p><ol><li>In the field table view, select the field and click <strong>Edit</strong>.</li><li>Update the field options as needed and click <strong>OK</strong>.</li></ol><blockquote><p>To support user-defined type converters or specific UDB driver versions, a custom JAR can be configured in the IMS Explorer connection settings.</p></blockquote><h2 id="moving-and-deleting-fields" tabindex="-1"><a class="header-anchor" href="#moving-and-deleting-fields" aria-hidden="true">#</a> Moving and deleting fields</h2><p><strong>To move a field:</strong></p><ol><li>Select one or more fields in the field table view and click <strong>Move</strong>.</li><li>Specify a byte position or select a target field to position the selected field after.</li></ol><p><strong>To delete a field:</strong></p><ol><li>Select one or more fields in the field table view and click <strong>Delete</strong>. Confirm when prompted.</li></ol><h2 id="additional-field-data-columns" tabindex="-1"><a class="header-anchor" href="#additional-field-data-columns" aria-hidden="true">#</a> Additional field data columns</h2><p>The field table view for catalog DBDs and PSBs includes additional data columns to provide more detail about each field.</p><h2 id="local-project-metadata-source" tabindex="-1"><a class="header-anchor" href="#local-project-metadata-source" aria-hidden="true">#</a> Local project metadata source</h2><p>When configuring an IMS connection in <code>ims.connections.json</code>, you can set <code>metadataSource</code> to <code>&quot;Local IMS Explorer Project&quot;</code> to use IMS catalog and local project metadata as the source for a database profile.</p>',17);function a(o,n){return d}var s=i(t,[["render",a]]);export{s as default};
